// HTTP client for the FinSight backend.
//
// The backend URL comes from window.FINSIGHT_CONFIG (config.js, generated by
// nginx from BACKEND_URL), so the portal and the API are deployed separately.
// Every call has a timeout; GET requests are retried with exponential backoff
// on network failures and gateway errors, mirroring the backend's own retry
// policy. Errors are normalised into ApiError using the backend's envelope
// {"error": {"code", "message", "request_id"}}.

const config = window.FINSIGHT_CONFIG || {};

export const BACKEND_URL = String(config.backendUrl || "http://localhost:8000").replace(/\/+$/, "");
export const MLFLOW_URL = String(config.mlflowUrl || "http://localhost:5000").replace(/\/+$/, "");
export const PROMETHEUS_URL = String(config.prometheusUrl || "http://localhost:9090").replace(/\/+$/, "");
export const GRAFANA_URL = String(config.grafanaUrl || "http://localhost:3000").replace(/\/+$/, "");
export const ALERTMANAGER_URL = String(config.alertmanagerUrl || "http://localhost:9093").replace(/\/+$/, "");

const RETRYABLE_STATUS = new Set([502, 504]);

export class ApiError extends Error {
  constructor(status, code, message, requestId = null) {
    super(message);
    this.name = "ApiError";
    this.status = status; // 0 = no response (network error, timeout, CORS)
    this.code = code;
    this.requestId = requestId;
  }

  get unreachable() {
    return this.status === 0;
  }
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Backoff before retry `attempt` (1, 2, ...): 400 ms, 800 ms, ... plus jitter. */
export function backoffMs(attempt, base = 400) {
  return base * 2 ** (attempt - 1) + Math.floor(Math.random() * 150);
}

async function once(path, { method, body, timeoutMs, signal }) {
  const controller = new AbortController();
  const onAbort = () => controller.abort();
  signal?.addEventListener("abort", onAbort, { once: true });
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(BACKEND_URL + path, {
      method,
      headers: body ? { "Content-Type": "application/json" } : undefined,
      body: body ? JSON.stringify(body) : undefined,
      signal: controller.signal,
    });
    const text = await response.text();
    let data = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = null;
    }
    if (!response.ok) {
      const err = data?.error || {};
      throw new ApiError(
        response.status,
        err.code || `http_${response.status}`,
        err.message || response.statusText || "request failed",
        err.request_id || response.headers.get("X-Request-ID"),
      );
    }
    return data;
  } catch (error) {
    if (error instanceof ApiError) throw error;
    if (signal?.aborted) throw error; // the page moved on: not an error to show
    const timedOut = controller.signal.aborted;
    throw new ApiError(
      0,
      timedOut ? "timeout" : "unreachable",
      timedOut ? "The server took too long to answer." : "Cannot reach the FinSight API.",
    );
  } finally {
    clearTimeout(timer);
    signal?.removeEventListener("abort", onAbort);
  }
}

/**
 * Call the API and return parsed JSON.
 * @param {string} path e.g. "/api/stock/AAPL?period=1M"
 * @param {{method?: string, body?: object, timeoutMs?: number, retries?: number, signal?: AbortSignal}} options
 */
export async function api(path, options = {}) {
  const method = options.method || "GET";
  const retries = options.retries ?? (method === "GET" ? 2 : 0);
  const timeoutMs = options.timeoutMs ?? 15000;
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await once(path, { method, body: options.body, timeoutMs, signal: options.signal });
    } catch (error) {
      const retryable = error instanceof ApiError && (error.unreachable || RETRYABLE_STATUS.has(error.status));
      if (!retryable || attempt >= retries || options.signal?.aborted) throw error;
      await sleep(backoffMs(attempt + 1));
    }
  }
}

export const endpoints = {
  stocks: (o) => api("/api/stocks", o),
  search: (q, o) => api(`/api/search?q=${encodeURIComponent(q)}&limit=10`, { retries: 0, timeoutMs: 5000, ...o }),
  stock: (ticker, period, o) => api(`/api/stock/${encodeURIComponent(ticker)}?period=${period}`, o),
  prediction: (ticker, o) => api(`/api/prediction/${encodeURIComponent(ticker)}`, { timeoutMs: 30000, ...o }),
  sentiment: (ticker, weeks, o) => api(`/api/sentiment/${encodeURIComponent(ticker)}?weeks=${weeks}`, o),
  portfolio: (o) => api("/api/portfolio", o),
  analyze: (texts, o) => api("/api/sentiment/analyze", { method: "POST", body: { texts }, timeoutMs: 30000, ...o }),
  health: (o) => api("/api/health", { retries: 0, timeoutMs: 8000, ...o }),
  modelInfo: (o) => api("/api/model-info", o),
  // Pipeline Console (Day 7)
  pipelineStatus: (o) => api("/api/pipeline/status", { retries: 0, timeoutMs: 10000, ...o }),
  pipelineRuns: ({ status = "", limit = 30 } = {}, o) =>
    api(`/api/pipeline/runs?limit=${limit}${status ? `&status=${encodeURIComponent(status)}` : ""}`, o),
  pipelineRun: (runId, o) => api(`/api/pipeline/runs/${encodeURIComponent(runId)}`, o),
  pipelineDag: (o) => api("/api/pipeline/dag", o),
  pipelineStats: (days, o) => api(`/api/pipeline/stats?days=${days}`, o),
  monitoring: (o) => api("/api/monitoring", { retries: 0, ...o }),
  pipelineTrigger: (kind, reason, o) => api("/api/pipeline/trigger", { method: "POST", body: { kind, reason }, ...o }),
};
